<?php
require __DIR__.'/includes/module.php';$u=require_auth();require_permission('quotations.view');if($_SERVER['REQUEST_METHOD']==='POST')require_permission('quotations.edit');$bid=(int)$u['business_id'];$id=(int)($_GET['id']??0);$s=db()->prepare('SELECT q.*,c.name customer,c.company,c.email,c.phone FROM quotations q JOIN customers c ON c.id=q.customer_id WHERE q.id=? AND q.business_id=?');$s->execute([$id,$bid]);$quote=$s->fetch();if(!$quote){http_response_code(404);exit('Quotation not found.');}$s=db()->prepare('SELECT * FROM quotation_items WHERE quotation_id=? ORDER BY id');$s->execute([$id]);$items=$s->fetchAll();page_start($quote['quotation_number'],'quotations');module_css('quotation-view');?><div class="section-head no-print"><div><span class="eyebrow">QUOTATION DETAILS</span><h1><?=e($quote['quotation_number'])?></h1><p><?=e($quote['customer'])?> · prepared <?=fmt_date($quote['quotation_date'])?></p></div><div class="quote-actions"><button class="button secondary" onclick="window.print()"><i class="ti ti-printer"></i> Print</button><?php if($quote['status']!=='Converted'):?><form method="post"><input type="hidden" name="_csrf" value="<?=e(csrf())?>"><input type="hidden" name="id" value="<?=$id?>"><input type="hidden" name="action" value="status"><select name="status" class="search"><option value="">Update status…</option><?php foreach(['Sent','Accepted','Rejected'] as $st):?><option value="<?=e($st)?>" <?=$quote['status']===$st?'disabled':''?>><?=e($st)?></option><?php endforeach?></select><button class="button secondary">Save</button></form><?php endif?><a class="button secondary" href="quotations.php">Back</a></div></div><article class="invoice-paper"><div class="invoice-brand"><div><span class="brand-mark"><i class="ti ti-chart-dots-3"></i></span><strong><?=e(json_decode($quote['business_snapshot']?:'{}',true)['name']??'BUZNET CRM')?></strong></div><span class="status"><?=e($quote['status'])?></span></div><div class="invoice-meta"><div><small>PREPARED FOR</small><strong><?=e(json_decode($quote['customer_snapshot']?:'{}',true)['name']??$quote['customer'])?></strong><span><?=e($quote['company']?:'')?><?= $quote['company']?'<br>':''?><?=e($quote['email']?:'')?><br><?=e($quote['phone']?:'')?></span></div><div><small>QUOTE DATE</small><strong><?=fmt_date($quote['quotation_date'])?></strong><small style="margin-top:14px">VALID UNTIL</small><strong><?=fmt_date($quote['valid_until'])?></strong></div></div><div class="table-scroll"><table class="data-table"><thead><tr><th>DESCRIPTION</th><th>QTY</th><th>RATE</th><th>TAX</th><th>AMOUNT</th></tr></thead><tbody><?php foreach($items as $i):?><tr><td class="table-strong"><?=e($i['description'])?></td><td><?=e($i['quantity'])?> <?=e($i['unit'])?></td><td><?=money($i['unit_price'])?></td><td><?=e($i['tax_rate'])?>% · <?=money($i['line_tax'])?></td><td class="table-strong"><?=money($i['line_total'])?></td></tr><?php endforeach?></tbody></table></div><div class="invoice-sums"><span>Subtotal <b><?=money($quote['subtotal'])?></b></span><span>Tax <b><?=money($quote['tax_total'])?></b></span><strong>Total <b><?=money($quote['total'])?></b></strong></div><?php if($quote['notes']):?><div class="invoice-notes"><small>NOTES / TERMS</small><p><?=nl2br(e($quote['notes']))?></p></div><?php endif?></article><?php if($quote['status']==='Accepted'&&!$quote['invoice_id']):?><form method="post" class="no-print" style="margin-top:14px" onsubmit="return confirm('Convert this accepted quotation to an issued invoice? The quotation will be preserved.')"><input type="hidden" name="_csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="convert"><input type="hidden" name="id" value="<?=$id?>"><button class="button primary"><i class="ti ti-file-invoice"></i> Convert to invoice</button></form><?php elseif($quote['invoice_id']):?><p class="no-print" style="margin-top:12px">Converted invoice: <a class="table-action" href="invoice-view.php?id=<?=(int)$quote['invoice_id']?>">View invoice</a></p><?php endif?><style>.invoice-paper{background:#fff;border:1px solid #edf0f2;border-radius:9px;padding:32px;max-width:850px}.invoice-brand{display:flex;justify-content:space-between;align-items:center;padding-bottom:22px;border-bottom:1px solid #edf0f2}.invoice-brand>div{display:flex;align-items:center;gap:10px}.invoice-brand strong{font:700 15px var(--display)}.invoice-meta{display:flex;justify-content:space-between;padding:23px 0}.invoice-meta>div{display:flex;flex-direction:column;align-items:flex-start;max-width:60%}.invoice-meta small,.invoice-notes small{font-size:8px;letter-spacing:1px;color:#9aa4ae;font-weight:700}.invoice-meta strong{font-size:11px;margin:5px 0}.invoice-meta span{font-size:10px;color:#83909d;line-height:1.8}.invoice-sums{width:min(300px,100%);margin:15px 0 0 auto;display:grid;gap:9px}.invoice-sums span,.invoice-sums strong{display:flex;justify-content:space-between;font-size:10px;color:#87919c}.invoice-sums strong{font-size:12px;color:#334050;border-top:1px solid #eef0f2;padding-top:10px}.invoice-notes{border-top:1px solid #eef0f2;padding-top:15px;margin-top:22px}.invoice-notes p{font-size:10px;color:#7b8794}.quote-actions{display:flex;align-items:center;gap:7px}.quote-actions form{display:flex;gap:5px}.quote-actions select{min-width:125px}@media(max-width:700px){.quote-actions{flex-wrap:wrap}.invoice-paper{padding:18px}}@media print{.sidebar,.topbar,.no-print{display:none!important}.main{margin:0}.page-content{padding:0}.invoice-paper{border:0;max-width:none}}</style><?php page_end();
